insert into public.local_matters (id, city, matter_id, file_number, title, type, status, body, intro_date, agenda_date, passed_date, legistar_url, last_modified, latest_action_date, latest_action_text, synced_at) values
  ('boston-43547', 'boston', 43547, '2026-1882', 'Emergency resolution calling for immediate relief for businesses devastated by the six-alarm fire at the historic Edison Building in Nubian Square.', 'Council Legislative Resolution', 'Passed', 'City Council', '2026-09-30', '2026-09-30', '2026-09-30', 'https://boston.legistar.com/gateway.aspx?M=L&ID=43547', '2026-10-06T20:54:23.493Z', '2026-09-30', 'The rules were suspended; the resolution was adopted.', '2026-10-08T05:23:06.115Z'),
  ('boston-43522', 'boston', 43522, '2026-1855', 'Order requesting certain information under Section 17F regarding the status of the Boston Reparations Task Force’s research, reports, and future work.', 'Council 17F Order', 'Passed', 'City Council', '2026-09-28', '2026-09-30', '2026-09-30', 'https://boston.legistar.com/gateway.aspx?M=L&ID=43522', '2026-10-02T15:26:57.000Z', '2026-09-30', 'The rules were suspended; the order was passed.', '2026-10-08T05:22:56.558Z'),
  ('boston-43495', 'boston', 43495, '2026-1839', 'Message and order authorizing the City of Boston to accept and expend the amount of Four Thousand Three Hundred Fifty Dollars ($4,350.00) in the form of a grant, The National Alliance of Preservation Commissions Scholarship, awarded by the Massachusetts Historical Commission to be administered by the Office of Historic Preservation. The grant would fund the cost of historical and historic district commission members, and municipal staff attending the National Alliance of Preservation Commissions (NAPC) FORUM conference.
insert into public.local_matter_actions (matter_id, seq, action_date, action_name, action_text, body, passed, event_id) values
  ('boston-43321', 1, '2026-09-16', 'The rules were suspended; the order was passed.', 'On motion of Councilor Louijeune, the rules were suspended; the order was passed: yeas 13 (Breadon, Coletta Zapata, Culpepper, Durkan, FitzGerald, Flynn, Louijeune, Mejia, Murphy, Pepén, Santana, Weber, Worrell).', 'City Council', null, 14238),
  ('boston-43322', 1, '2026-09-16', 'The rules were suspended; the order was passed.', 'On motion of Councilor Murphy, the rules were suspended; the order was passed: yeas 13 (Breadon, Coletta Zapata, Culpepper, Durkan, FitzGerald, Flynn, Louijeune, Mejia, Murphy, Pepén, Santana, Weber, Worrell).', 'City Council', null, 14238),
  ('boston-43323', 1, '2026-09-16', 'The rules were suspended; the order was passed.', 'Referred to the Committee on Human Services.
