insert into public.discussions (id, title, prompt, jurisdiction, district, target_type, target_id, status, residency_required) values
  ('example-boston-ordinance', 'Example: what should the City Council weigh on Docket #2026-1882?', 'This is an example discussion for local development. Docket #2026-1882: Emergency resolution calling for immediate relief for businesses devastated by the six-alarm fire at the historic Edison Building in Nubian Square.
